"use client";

/**
 * DateTile. The page of a desk calendar: the weekday and month engraved
 * small on a raised tile, the day huge on the screen set into it. Change the
 * date and the day turns over to the new one, like a tear-off page.
 *
 * `sm` sits in a list row (an event, a booking, an invoice due), `md` on a
 * card, `lg` on its own as a widget. For assistive technology it is one date,
 * said in full.
 */
import { SegmentDisplay } from "../segment-display";
import { dayOfMonth, spell } from "./dates";
import "../panel/panel.css";
import "../scope/scope.css";
import "./date-tile.css";

export interface DateTileProps {
  /** The day, as an ISO date: "2026-09-25". */
  date: string;
  /** `sm` for a list row, `md` (default) for a card, `lg` as a widget. */
  size?: "sm" | "md" | "lg";
  /** A new date turns over to its day instead of swapping it. */
  roll?: boolean;
  /** The language the weekday and month are engraved in. Default "en". */
  locale?: string;
  /** `emissive` (default): a dark screen that glows. `reflective`: the paper-coloured glass of a pocket calculator, printed in ink. */
  screen?: "emissive" | "reflective";
}

export function DateTile({ date, size = "md", roll = false, locale = "en", screen = "emissive" }: DateTileProps) {
  const iso = date.slice(0, 10);
  return (
    <time className="echo-panel echo-date-tile" data-variant="raised" data-size={size} dateTime={iso}>
      <span className="echo-date-tile__top" aria-hidden="true">
        <span className="echo-date-tile__weekday">{spell(iso, locale, { weekday: "short" })}</span>
        <span className="echo-date-tile__month">{spell(iso, locale, { month: "short" })}</span>
      </span>
      <span className="echo-date-tile__screen" aria-hidden="true" data-echo-screen={screen === "reflective" ? "reflective" : undefined}>
        <SegmentDisplay variant="flush" label="Day" value={String(dayOfMonth(iso))} digits={2} pad=" " size={size} roll={roll} />
      </span>
      <span className="echo-date-tile__said">
        {spell(iso, locale, { weekday: "long", day: "numeric", month: "long", year: "numeric" })}
      </span>
    </time>
  );
}

/**
 * DateTile. Panel's raised plastic, with the weekday and month engraved on
 * it and a screen set into it for the day. Composes var(--echo-*) — no hex
 * literals; the only fixed values are the single-key-light model.
 */
.echo-date-tile {
  --dt-gap: var(--echo-space-3);
  --dt-pad: var(--echo-space-4);
  display: inline-grid;
  gap: var(--dt-gap);
  padding: var(--dt-pad);
  border-radius: var(--echo-radius-2xl);
  vertical-align: middle;
  min-inline-size: 0;
}
.echo-date-tile[data-size="sm"] {
  --dt-gap: var(--echo-space-2);
  --dt-pad: var(--echo-space-3);
  border-radius: var(--echo-radius-lg);
}
.echo-date-tile[data-size="lg"] {
  --dt-gap: var(--echo-space-4);
  --dt-pad: var(--echo-space-6);
  border-radius: var(--echo-radius-3xl);
}

.echo-date-tile__top {
  display: flex;
  justify-content: space-between;
  gap: var(--echo-space-4);
  padding-inline: var(--echo-space-2);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  text-transform: uppercase;
  line-height: var(--echo-leading-tight, 1.25);
}
.echo-date-tile__weekday {
  color: var(--echo-text);
}
.echo-date-tile__month {
  color: var(--echo-text-dim);
}
.echo-date-tile[data-size="lg"] .echo-date-tile__top {
  font-size: var(--echo-text-2xs);
}

/* The screen set into the tile, the day lit on it. */
.echo-date-tile__screen {
  display: grid;
  place-items: center;
  padding: var(--echo-space-5) var(--echo-space-6);
  border-radius: var(--echo-radius-lg);
  background: linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%);
  box-shadow: var(
    --echo-shadow-well-screen,
    inset 0 2px 6px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.8 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.05 * var(--echo-gloss, 1)))
  );
}
.echo-date-tile[data-size="sm"] .echo-date-tile__screen {
  padding: var(--echo-space-3) var(--echo-space-4);
  border-radius: var(--echo-radius-md);
}

.echo-date-tile__said {
  position: absolute;
  inline-size: 1px;
  block-size: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@media (forced-colors: active) {
  .echo-date-tile,
  .echo-date-tile__screen {
    border: var(--echo-border-hairline, 1px) solid CanvasText;
  }
}

/**
 * Days as ISO dates ("2026-09-25"). Pure: no React, no DOM.
 *
 * Everything is worked in UTC and formatted in UTC, so a day is the same day
 * on the server and in every browser, whatever time zone either is in: a
 * day picker that renders the 24th on the server and the 25th in Tokyo is a
 * hydration mismatch and a wrong answer.
 */

const DAY = 86_400_000;

/** Midnight UTC of an ISO date, as a timestamp. */
export function at(iso: string): number {
  const [y = 1970, m = 1, d = 1] = iso.slice(0, 10).split("-").map(Number);
  return Date.UTC(y, m - 1, d);
}

/** The ISO date of a timestamp. */
export function isoOf(time: number): string {
  return new Date(time).toISOString().slice(0, 10);
}

/** The day `n` days after `iso` (before it, for a negative `n`). */
export function addDays(iso: string, n: number): string {
  return isoOf(at(iso) + n * DAY);
}

/** The first day of the week `iso` falls in: Monday (1, default) or Sunday (0). */
export function weekStart(iso: string, startsOn: 0 | 1 = 1): string {
  const weekday = new Date(at(iso)).getUTCDay();
  return addDays(iso, -((weekday - startsOn + 7) % 7));
}

/** The seven days of the week `iso` falls in. */
export function weekOf(iso: string, startsOn: 0 | 1 = 1): string[] {
  const first = weekStart(iso, startsOn);
  return Array.from({ length: 7 }, (_, i) => addDays(first, i));
}

/** A day's parts in words, in `locale`: "Fri", "Friday", "Sep", "25 September 2026"… */
export function spell(iso: string, locale: string, options: Intl.DateTimeFormatOptions): string {
  return new Intl.DateTimeFormat(locale, { ...options, timeZone: "UTC" }).format(at(iso));
}

/** The day of the month, as a number. */
export function dayOfMonth(iso: string): number {
  return new Date(at(iso)).getUTCDate();
}
